const menuButton=document.querySelector('.menu-toggle');const nav=document.querySelector('#site-nav');menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')==='true';menuButton.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}));document.querySelectorAll('.day button').forEach(button=>button.addEventListener('click',()=>{const day=button.closest('.day');const wasOpen=day.classList.contains('active');document.querySelectorAll('.day').forEach(item=>{item.classList.remove('active');item.querySelector('button').setAttribute('aria-expanded','false');item.querySelector('i').textContent='+'});if(!wasOpen){day.classList.add('active');button.setAttribute('aria-expanded','true');button.querySelector('i').textContent='−'}}));const modal=document.querySelector('.booking-modal');document.querySelector('.booking').addEventListener('click',()=>modal.showModal());modal.querySelector('.close').addEventListener('click',()=>modal.close());modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});modal.querySelectorAll('[data-date]').forEach(button=>button.addEventListener('click',()=>{modal.querySelector('.confirmation').textContent=`Wonderful — ${button.dataset.date} is marked for you. We look forward to meeting in the woods.`}));
